void dei_rs_rf_runtime_reset( void *remote )
{	
	if( !dei_rs_state ) 
	{
		notify_send( NOTIFY_RANGE_CHECK ) ; 
	}
	else
	{
		dei_rs_runtime_reset(); 
				
		notify_send( NOTIFY_RUNTIME_RESET , get_rs_runtime_programmed() ) ; 				
	}
}
//--------------------------------------------------------------------------//

void dei_rs_rf_runtime_check( void *remote )
{	
	if( !dei_rs_state ) //remote start is off
	{
		notify_send( NOTIFY_RANGE_CHECK ) ; 
	}
	else
	{
		notify_send( NOTIFY_RUNTIME_CHECK , get_rs_runtime_remaining() ) ; 				
	}
}
